package com.bundledrop

import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Test

class BundleDropRuntimeCryptoTest {
  private val protectedHeader = "eyJhbGciOiJFUzI1NiIsImtpZCI6InRlc3Qta2V5LTIwMjYtMDgiLCJ0eXAiOiJidW5kbGVkcm9wLW1hbmlmZXN0K2p3cyJ9"
  private val payload = ""
  private val signature = "PnYXxiTNWHH5_aV-875FSk_Lne73VUZHAh59nV_a7oWJl1b2BBWLZ3_0e32Oprtgx5QnZWwMvl_wBznLM6WRdg"
  private val x = "d-g4y_28QdARnFF6HO0T00laLEfHhVFXTmuWHqBWmfM"
  private val y = "_Z_xWbhjDp3IVMtLA_rN3guVyprP34OvBikPWpVQfUI"

  @Test
  fun matchesSha256GoldenVector() {
    assertEquals("8ed3f6ad685b959ead7022518e1af76cd816f8e8ec7ccdda1ed4018e8f2223f8", BundleDropRuntimeCrypto.sha256String("alpha"))
  }

  @Test
  fun verifiesCrossRepositoryGoldenSignature() {
    assertTrue(BundleDropRuntimeCrypto.verifyEs256Signature("$protectedHeader.$payload", signature, x, y))
  }

  @Test
  fun rejectsTamperedSignatureAndPayload() {
    assertFalse(BundleDropRuntimeCrypto.verifyEs256Signature("$protectedHeader.${payload}A", signature, x, y))
    val tampered = signature.dropLast(1) + if (signature.last() == 'A') "B" else "A"
    assertFalse(BundleDropRuntimeCrypto.verifyEs256Signature("$protectedHeader.$payload", tampered, x, y))
  }
}
